export type Category = "primary" | "social" | "promotions" | "updates";

export type Contact = {
  name: string;
  email: string;
};

export type Attachment = {
  id: string;
  name: string;
  size: number;
  mime: string;
  dataUrl?: string;
};

export type Message = {
  id: string;
  from: Contact;
  to: Contact[];
  cc?: Contact[];
  bcc?: Contact[];
  date: string;
  body: string;
  bodyHtml?: string;
  quote?: string;
  attachments?: Attachment[];
  confidential?: boolean;
};

export type Thread = {
  id: string;
  subject: string;
  category: Category;
  labels: string[];
  starred: boolean;
  read: boolean;
  important: boolean;
  snoozedUntil: string | null;
  messages: Message[];
};

export type Draft = {
  id: string;
  threadId?: string;
  messageId?: string;
  mode: "new" | "reply" | "replyAll" | "forward";
  to: string[];
  cc: string[];
  bcc: string[];
  subject: string;
  bodyHtml: string;
  quote?: string;
  attachments: Attachment[];
  confidential: boolean;
  scheduledFor: string | null;
  showCc: boolean;
  showBcc: boolean;
  updatedAt: string;
};

export type Label = {
  id: string;
  name: string;
  color: string;
};

export type Settings = {
  density: "default" | "comfortable" | "compact";
  theme: "light" | "dark" | "system";
  readingPane: boolean;
  sortUnreadFirst: boolean;
  signature: string;
  signatureOn: boolean;
};

