  monday.setDate(now.getDate() + add);
  monday.setHours(8, 0, 0, 0);
  const nextWeek = new Date(now);
  nextWeek.setDate(now.getDate() + 7);
  nextWeek.setHours(8, 0, 0, 0);
  const items = [
