    starred: "Starred",
    snoozed: "Snoozed",
    sent: "Sent",
    drafts: "Drafts",
    scheduled: "Scheduled",
    all: "All mail",
    spam: "Spam",
    trash: "Trash",
  };
  return names[id] ?? id;
}

