  const wantsSpam = tokens.some((token) => token.toLowerCase() === "in:spam");
  return threads.filter((thread) => {
    if (!wantsTrash && thread.labels.includes("trash")) return false;
    if (!wantsSpam && thread.labels.includes("spam")) return false;
