            <Icon name={icon} size={18} />
            {label}
            {count > 0 && <span className="count">{count}</span>}
          </button>
        );
      })}
    </div>
  );
}

export function actionIds(mail: ReturnType<typeof useMail>, menu?: MenuState | null): string[] {
