  { id: "starred", icon: "star" },
  { id: "snoozed", icon: "clock" },
  { id: "sent", icon: "send" },
  { id: "drafts", icon: "file" },
  { id: "scheduled", icon: "calendar" },
  { id: "all", icon: "layers" },
  { id: "spam", icon: "spam" },
  { id: "trash", icon: "trash" },
