      } else if (event.key === "?") api.dispatch({ type: "dialog", dialog: { type: "shortcuts" } });
      else if (event.key === "I") {
        const chosen = ids();
        if (chosen.length) api.dispatch({ type: "read", ids: chosen, read: true });
      } else if (event.key === "U") {
        const chosen = ids();
        if (chosen.length) api.dispatch({ type: "read", ids: chosen, read: false });
      }
    };
