                {file.name}
                <small>{formatBytes(file.size)}</small>
              </span>
            </button>
          ))}
        </div>
      ) : null}
      {message.quote && (
        quote ? <div className="quote">{message.quote}</div> : <button className="quote-toggle" onClick={() => setQuote(true)} aria-label="Show quoted text">…</button>
      )}
    </>
  );
}

