function RichText({ html, onChange, focusNonce }: { html: string; onChange: (html: string) => void; focusNonce: number }) {
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const node = ref.current;
    if (!node) return;
    if (document.activeElement !== node && node.innerHTML !== html) node.innerHTML = html;
  }, [html]);
  useEffect(() => {
    if (focusNonce) ref.current?.focus();
  }, [focusNonce]);
  return (
    <div className="editor-wrap">
      <div
        ref={ref}
        className="editor"
        contentEditable
        role="textbox"
        aria-multiline="true"
        aria-label="Message body"
        data-placeholder="Write your message"
