function DateTime({ purpose, ids, draftId }: { purpose: "snooze" | "schedule"; ids?: string[]; draftId?: string }) {
  const mail = useMail();
  const [value, setValue] = useState("");
  return (
    <>
      <h2>{purpose === "snooze" ? "Snooze until" : "Schedule send"}</h2>
