  padding: 0 8px 0 12px;
  flex: none;
}
.toolbar .grow { flex: 1; }
.pager { display: flex; align-items: center; color: var(--faint); font-size: 12px; gap: 2px; flex: none; }
.box-title { font-weight: 500; margin: 0 8px; }
.check-wrap, .pop-anchor { position: relative; display: flex; align-items: center; }
.star-on { color: var(--star); }
.btn.ghost.on { background: var(--nav-active); color: var(--nav-text); }
.check-wrap input { width: 18px; height: 18px; accent-color: var(--blue); }
.tabs {
  display: flex;
  gap: 0;
  padding: 0 16px;
  border-bottom: 1px solid transparent;
  flex: none;
}
.tab {
  height: 44px;
  padding: 0 16px;
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--muted);
  border-bottom: 3px solid transparent;
  font-weight: 500;
}
.tab.active { color: var(--text); }
.tab.primary.active { border-color: #0b57d0; color: #0b57d0; }
.tab.social.active { border-color: #1a73e8; color: #1a73e8; }
.tab.promotions.active { border-color: #188038; color: #188038; }
.tab.updates.active { border-color: #e37400; color: #e37400; }
:root[data-theme="dark"] .tab.primary.active,
:root[data-theme="dark"] .tab.social.active { color: #a8c7fa; border-color: #a8c7fa; }
:root[data-theme="dark"] .tab.promotions.active { color: #81c995; border-color: #81c995; }
:root[data-theme="dark"] .tab.updates.active { color: #fcbd00; border-color: #fcbd00; }
.tab .count { font-size: 12px; }

.content { flex: 1; min-height: 0; display: flex; }
.content.split .list-pane { width: min(46%, 560px); flex: none; border-right: 1px solid var(--line); }
.content.split .thread-pane { flex: 1; min-width: 0; }
.list-pane, .thread-pane, .list-scroll, .thread-scroll { min-height: 0; }
.list-scroll, .thread-scroll { overflow: auto; height: 100%; }

.row {
  display: grid;
  grid-template-columns: 28px 28px minmax(88px, 196px) minmax(0, 1fr) auto;
  align-items: center;
  column-gap: 6px;
  min-height: var(--row);
  margin: 1px 8px;
  padding: 0 8px 0 8px;
  border-radius: var(--radius);
  color: var(--text);
  position: relative;
}
.row.unread { background: var(--surface); }
.row.read .sender, .row.read .subject-strong, .row.read .date { font-weight: 400; }
.row.unread .sender, .row.unread .subject-strong, .row.unread .date, .row.unread .count { font-weight: 700; }
.row:hover { box-shadow: inset 0 0 0 1px transparent, var(--shadow); background: var(--surface); z-index: 1; }
.row.selected { background: var(--selected); }
.row.cursor { box-shadow: inset 0 0 0 1px var(--blue); }
.sender-col { display: flex; align-items: baseline; min-width: 0; gap: 4px; }
.sender, .subject-strong, .snippet, .date { white-space: nowrap; }
.sender { overflow: hidden; text-overflow: ellipsis; }
.count { color: var(--faint); font-size: 12px; flex: none; }
.subject-cell { display: flex; align-items: center; gap: 8px; min-width: 0; }
.subject-line { display: flex; min-width: 0; gap: 6px; overflow: hidden; }
.snippet { overflow: hidden; text-overflow: ellipsis; color: var(--faint); font-weight: 400; }
.subject-strong { flex: none; max-width: 46%; overflow: hidden; text-overflow: ellipsis; }
.date { font-size: 12px; color: var(--faint); width: 76px; text-align: right; }
.row.unread .date { color: var(--text); }
.chips { display: flex; gap: 4px; flex: none; }
.chip {
  font-size: 11px;
  font-weight: 500;
  line-height: 16px;
  border-radius: 4px;
  padding: 0 4px;
  background: color-mix(in srgb, var(--c) 18%, transparent);
  color: var(--c);
}
.chip.draft { --c: #d93025; color: #d93025; }
.row-actions {
  display: none;
  position: absolute;
  right: 8px;
  top: 50%;
  transform: translateY(-50%);
  background: var(--surface);
  border-radius: 16px;
}
.row:hover .row-actions, .row:focus-within .row-actions { display: flex; }
.row:hover .date, .row:focus-within .date { visibility: hidden; }
.bang { color: #f9ab00; display: grid; }

.empty {
  height: 100%;
  min-height: 240px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  color: var(--faint);
  gap: 8px;
  text-align: center;
  padding: 24px;
}
.empty h2 { margin: 8px 0 0; font-size: 18px; font-weight: 400; color: var(--muted); }
.empty p { margin: 0; max-width: 360px; }

.thread-scroll { padding: 8px 12px 32px; }
.thread-subject {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 8px 8px 12px;
}
.thread-subject h2 { margin: 0; font-size: 22px; font-weight: 400; line-height: 1.3; }
.subject-tools { margin-left: auto; display: flex; align-items: center; gap: 4px; }
.message {
  background: var(--surface);
  border-radius: 16px;
  margin: 0 0 10px;
  box-shadow: var(--shadow);
}
.message.collapsed { cursor: pointer; }
.message-head {
  display: flex;
  gap: 12px;
  align-items: flex-start;
  padding: 14px 16px;
}
.message.collapsed .message-head { align-items: center; padding-top: 10px; padding-bottom: 10px; }
.message-meta { flex: 1; min-width: 0; }
.message-meta .who { display: flex; gap: 8px; align-items: baseline; }
.message-meta .name { font-weight: 700; }
.message-meta .email, .message-meta .to-line { color: var(--faint); font-size: 12px; }
.to-line { background: none; padding: 0; }
.when { color: var(--faint); font-size: 12px; white-space: nowrap; }
.msg-actions { display: flex; }
.body { padding: 0 16px 8px 68px; white-space: pre-wrap; line-height: 1.55; overflow-wrap: anywhere; }
.body.html p { margin: 0 0 10px; }
.quote {
  margin: 8px 16px 16px 68px;
  border-left: 2px solid var(--line);
  padding-left: 12px;
  color: var(--muted);
  white-space: pre-wrap;
}
.quote-toggle { margin-left: 68px; margin-bottom: 12px; color: var(--faint); font-size: 18px; letter-spacing: 1px; height: 24px; }
.files { display: flex; flex-wrap: wrap; gap: 8px; padding: 0 16px 16px 68px; }
.file-chip {
  display: flex;
  align-items: center;
  gap: 8px;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 8px 10px;
  background: var(--bg);
  max-width: 240px;
  text-align: left;
}
.file-chip span { display: block; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; max-width: 160px; }
.file-chip small { color: var(--faint); }
.banner {
  margin: 0 16px 12px 68px;
  background: var(--surface-3);
  border-radius: 8px;
  padding: 8px 10px;
  color: var(--muted);
  font-size: 13px;
}
.earlier {
  width: 100%;
  height: 36px;
  border-radius: 18px;
  background: var(--surface);
  margin-bottom: 10px;
  color: var(--muted);
  box-shadow: var(--shadow);
}

.composer {
  background: var(--surface);
  border-radius: 16px;
  box-shadow: var(--shadow);
  padding: 8px 8px 10px;
}
.composer.dock {
  position: fixed;
  right: 24px;
  bottom: 0;
  width: min(508px, calc(100vw - 24px));
  height: 480px;
  z-index: 30;
  display: flex;
  flex-direction: column;
  border-radius: 8px 8px 0 0;
  box-shadow: 0 8px 10px 1px rgba(0,0,0,.14), 0 3px 14px 2px rgba(0,0,0,.12), 0 5px 5px -3px rgba(0,0,0,.2);
  padding: 0;
}
.composer.dock.expanded {
  inset: 24px 24px 0 280px;
  width: auto;
  height: auto;
}
.composer.dock.min {
  height: 40px;
  width: min(280px, calc(100vw - 24px));
  cursor: pointer;
}
.dock-bar {
  height: 40px;
  background: var(--surface-3);
  border-radius: 8px 8px 0 0;
  display: flex;
  align-items: center;
  padding: 0 8px 0 16px;
  font-weight: 500;
  gap: 4px;
}
.dock-bar span { flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.composer-fields { display: flex; flex-direction: column; min-height: 0; flex: 1; padding: 0 4px; }
.field {
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 36px;
  border-bottom: 1px solid var(--line);
  padding: 4px 8px;
  position: relative;
}
.field label, .field-label { color: var(--faint); width: 28px; flex: none; }
.field input[type="text"], .field input[type="email"] {
  flex: 1;
  border: 0;
  outline: none;
  background: transparent;
  min-width: 40px;
  height: 28px;
}
.chips-inline { display: flex; flex-wrap: wrap; gap: 4px; align-items: center; flex: 1; }
.person-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  background: var(--surface-3);
  border-radius: 12px;
  padding: 2px 6px 2px 2px;
  max-width: 220px;
}
.person-chip b { font-weight: 500; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.linkish { color: var(--blue); background: none; font-size: 13px; }
.suggest {
  position: absolute;
  left: 36px;
  right: 8px;
  top: calc(100% - 2px);
  background: var(--surface);
  box-shadow: var(--pop);
  border-radius: 8px;
  z-index: 5;
  max-height: 240px;
  overflow: auto;
  padding: 6px 0;
}
.suggest button {
  width: 100%;
  display: flex;
  gap: 10px;
  align-items: center;
  padding: 6px 12px;
  text-align: left;
}
.suggest button.active, .suggest button:hover { background: var(--hover); }
.suggest small { color: var(--faint); display: block; }
.editor-wrap { position: relative; flex: 1; min-height: 120px; display: flex; }
.editor {
  flex: 1;
  min-height: 140px;
  padding: 12px;
  outline: none;
  overflow: auto;
  line-height: 1.5;
}
.editor:empty::before { content: attr(data-placeholder); color: var(--faint); }
.sig { color: var(--faint); padding: 0 12px 8px; white-space: pre-wrap; font-size: 13px; }
.composer-bar {
  display: flex;
  align-items: center;
  gap: 2px;
  padding: 8px;
}
.send-split { display: flex; margin-right: 8px; }
.send-split .send {
  background: var(--blue);
  color: white;
  height: 36px;
  padding: 0 16px;
  border-radius: 18px 0 0 18px;
  font-weight: 500;
}
.send-split .caret {
  background: var(--blue);
  color: white;
  width: 32px;
  border-radius: 0 18px 18px 0;
  border-left: 1px solid rgba(255,255,255,.35);
  display: grid;
  place-items: center;
}
.send.solo { border-radius: 18px; }
.format-btn { width: 32px; height: 32px; border-radius: 6px; color: var(--muted); display: grid; place-items: center; }
.format-btn:hover, .format-btn.on { background: var(--hover); }
.format-btn.text { font-weight: 700; width: 32px; }
.form-error { color: var(--danger); font-size: 12px; padding: 0 12px 4px; }
.schedule-note { margin: 8px 12px 0; background: #d3e3fd; color: #041e49; border-radius: 8px; padding: 8px 10px; display: flex; justify-content: space-between; gap: 8px; }
:root[data-theme="dark"] .schedule-note { background: #004a77; color: #c2e7ff; }

.menu {
  position: absolute;
  z-index: 50;
  background: var(--surface);
  box-shadow: var(--pop);
  border-radius: 8px;
  min-width: 220px;
  padding: 6px 0;
  color: var(--text);
}
.menu.fixed { position: fixed; }
.menu button, .menu label.rowish {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 16px;
  text-align: left;
  background: none;
}
.menu button:hover, .menu label.rowish:hover { background: var(--hover); }
.menu .hint { margin-left: auto; color: var(--faint); font-size: 12px; }
.menu hr { border: 0; border-top: 1px solid var(--line); margin: 6px 0; }
.account-card { padding: 12px 16px 8px; }
.account-card strong { display: block; }
.account-card span { color: var(--faint); font-size: 12px; }
.quiet { padding: 4px 16px 8px; color: var(--faint); font-size: 12px; }

.dialog-scrim {
  position: fixed;
  inset: 0;
  background: rgba(32, 33, 36, 0.46);
  z-index: 60;
  display: grid;
  place-items: center;
  padding: 24px;
}
.dialog {
  width: min(560px, 100%);
  background: var(--surface);
  color: var(--text);
  border-radius: 28px;
  box-shadow: var(--pop);
  padding: 20px 24px 16px;
  max-height: min(80vh, 720px);
  overflow: auto;
}
.dialog h2 { margin: 0 0 12px; font-size: 22px; font-weight: 400; }
.dialog p { color: var(--muted); }
.dialog-actions { display: flex; justify-content: flex-end; gap: 8px; margin-top: 16px; }
.btn {
  height: 36px;
  padding: 0 16px;
  border-radius: 18px;
  font-weight: 500;
}
.btn.primary { background: var(--blue); color: white; }
.btn.danger { color: var(--danger); }
.btn.ghost:hover { background: var(--hover); }
.settings-grid { display: grid; gap: 14px; }
.settings-grid h3 { margin: 8px 0 4px; font-size: 13px; font-weight: 500; color: var(--muted); }
.choice { display: flex; gap: 8px; flex-wrap: wrap; }
.choice button, .swatch {
  border: 1px solid var(--line);
  border-radius: 16px;
  padding: 6px 12px;
  background: transparent;
}
.choice button.on { background: var(--nav-active); border-color: transparent; color: var(--nav-text); font-weight: 500; }
.swatches { display: flex; gap: 8px; }
.swatch { width: 28px; height: 28px; border-radius: 50%; padding: 0; }
.swatch.on { outline: 2px solid var(--text); outline-offset: 2px; }
label.stack { display: grid; gap: 6px; font-size: 13px; color: var(--muted); }
label.stack input[type="text"], label.stack textarea, label.stack input[type="datetime-local"] {
  border: 1px solid var(--line);
  background: var(--bg);
  border-radius: 8px;
  padding: 8px 10px;
  color: var(--text);
}
.toggle { display: flex; align-items: center; gap: 8px; }
.keys { width: 100%; border-collapse: collapse; }
.keys td { padding: 6px 8px; border-bottom: 1px solid var(--line); }
.keys td:first-child { color: var(--muted); white-space: nowrap; width: 42%; }
kbd {
  font-family: var(--font);
  border: 1px solid var(--line);
  border-radius: 4px;
  padding: 1px 6px;
  background: var(--surface-3);
}

.toast {
  position: fixed;
  left: 24px;
  bottom: 24px;
  z-index: 70;
  background: #322f35;
  color: #f3f0f4;
  min-height: 48px;
  padding: 8px 8px 8px 16px;
  border-radius: 4px;
  display: flex;
  align-items: center;
  gap: 12px;
  box-shadow: var(--pop);
  max-width: min(420px, calc(100vw - 32px));
}
.toast button { color: #d3e3fd; font-weight: 500; height: 36px; padding: 0 12px; border-radius: 4px; }
.toast button:hover { background: rgba(211, 227, 253, 0.12); }
mark { background: #fde293; color: inherit; border-radius: 2px; }
:root[data-theme="dark"] mark { background: #6d5a16; color: white; }

.preview-img { max-width: 100%; border-radius: 8px; margin-top: 8px; }
.sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); }

@media (max-width: 840px) {
  .wordmark { width: auto; font-size: 18px; }
  .side {
    position: fixed;
    z-index: 45;
    top: 0;
    bottom: 0;
    left: 0;
    width: min(300px, 88vw);
    background: var(--bg);
    transform: translateX(-105%);
    transition: transform 160ms ease;
    padding-top: 12px;
    box-shadow: var(--pop);
  }
  .side.open { transform: none; }
  .search { display: none; }
  .mobile-search { display: grid; }
  .search.overlay {
    display: flex;
    position: absolute;
    left: 8px;
    right: 8px;
    top: 8px;
    max-width: none;
    z-index: 5;
    height: 48px;
  }
  .content.split { flex-direction: column; }
  .content.split .list-pane { width: auto; border-right: 0; }
  .subject-strong { max-width: 70%; }
  .chips, .snippet { display: none; }
  .row { grid-template-columns: 24px 24px minmax(72px, 120px) minmax(0, 1fr) auto; }
  .composer.dock, .composer.dock.expanded {
    inset: 0;
    width: auto;
    height: auto;
    border-radius: 0;
  }
  .composer.dock.min { inset: auto 8px 0 auto; height: 40px; width: min(240px, 70vw); }
  .body, .quote, .files, .banner, .quote-toggle { margin-left: 16px; padding-left: 0; }
  .body { padding: 0 16px 12px; }
  .box-title { display: none; }
  .thread-subject h2 { font-size: 18px; }
}

@media (min-width: 841px) {
  .box-title.mobile-only { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; }
}

@media print {
  .topbar, .side, .toolbar, .tabs, .composer, .toast, .row-actions, .msg-actions, .scrim, .dialog-scrim { display: none !important; }
  .workspace, .main, .content, .thread-pane, .thread-scroll { display: block; height: auto; overflow: visible; }
  .message { box-shadow: none; border: 1px solid #ccc; }
}

success.afterFullFileContent:
:root {
