    );
  }
  return <Composer draft={draft} variant="inline" />;
}

function Composer({
  draft,
  variant,
  minimized = false,
  expanded = false,
}: {
  draft: Draft;
  variant: "dock" | "inline";
  minimized?: boolean;
  expanded?: boolean;
}) {
