          </div>
        )}
        <Recipients
          label="To"
          values={draft.to}
          contacts={mail.contacts}
          onChange={(to) => patch({ to })}
          trailing={
            <>
              {!draft.showCc && <button className="linkish" onClick={() => patch({ showCc: true })}>Cc</button>}
