        </div>
        <RichText html={draft.bodyHtml} draftId={draft.id} focusNonce={mail.focusNonce} onChange={(bodyHtml) => patch({ bodyHtml })} />
        {mail.settings.signatureOn && <div className="sig">{mail.settings.signature}</div>}
